// Verus program for validating a postal code pattern.
//
// Rule:
// - s.len() == a + b + 1
// - exactly one '-' and it must be at index a (0-based)
// - all other characters must be digits '0'..'9'
// Return: ['Y','e','s'] if valid else ['N','o']

#![allow(unused_imports)]
use vstd::prelude::*;

